import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String orgId = req.getParameter("org_id");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // HTML-escape org_id for XSS prevention in error messages
        String safeOrgId = StringEscapeUtils.escapeHtml4(orgId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildReportQuery(reportType, dateRange, sortCol, orgId);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));

        } catch (SQLException e) {
            resp.sendError(500, "Database error for org: " + safeOrgId);
        }
    }

    private String buildReportQuery(String type, String range, String sortCol, String orgId) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT id, title, created_at, amount FROM reports WHERE type = '");
        sb.append(type).append("'");

        if (range != null) {
            String[] parts = range.split("_");
            sb.append(" AND created_at BETWEEN '").append(parts[0]).append("' AND '").append(parts[1]).append("'");
        }

        if (orgId != null) {
            sb.append(" AND org_id = '").append(orgId).append("'");
        }

        // Sort column - developer assumed whitelist check covers this
        if (sortCol != null) {
            sb.append(" ORDER BY ").append(sortCol);
        }

        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        String[] valid = {"financial", "operational", "compliance", "audit"};
        for (String v : valid) {
            if (v.equals(type)) return true;
        }
        return false;
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append(String.format(
                "{\"id\":%d,\"title\":\"%s\",\"created_at\":\"%s\",\"amount\":%.2f}",
                rs.getInt("id"),
                rs.getString("title").replace("\"", "\\\""),
                rs.getString("created_at"),
                rs.getDouble("amount")
            ));
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
